arguments.command:
mkdir -p /workspace/project/include && cat > /workspace/project/include/collector.h <<'EOF'
#ifndef EPIC_COLLECTOR_H
#define EPIC_COLLECTOR_H

#include <stddef.h>
#include <stdint.h>

#include "offline_api.h"

/* Offline four-port collective collector (contract: PROTOCOL.md).
 *
 * The collector owns the retained window, the cumulative upstream/downstream
 * acknowledgement bookkeeping, the emission priority and the retirement of
 * completed logical inputs.  It never touches a NIC: every egress frame is
 * handed to the offline emit callback.
 */
typedef struct collector collector_t;

collector_t *collector_open(int primitive, int mode, int root, uint32_t count,
                            uint32_t words, uint32_t capacity, uint32_t start,
                            epic_emit_fn emit, void *user);
void collector_close(collector_t *ctx);
int collector_ingress(collector_t *ctx, int rank, const uint8_t *frame, size_t length);
int collector_flush(collector_t *ctx);
int collector_retry(collector_t *ctx, int rank);
void collector_state(collector_t *ctx, uint64_t *state);
uint64_t collector_digest(collector_t *ctx);

#endif
EOF
echo written
